    $qty=New-Object Windows.Forms.NumericUpDown;$qty.Minimum=1;$qty.Maximum=255;$qty.Value=1;$qty.Location='465,235';$qty.Size='75,28';$gameTab.Controls.Add($qty);$ga=New-Object Windows.Forms.Button;$ga.Text='← 增加';$ga.Location='460,275';$ga.Size='80,34';$gameTab.Controls.Add($ga);$gd=New-Object Windows.Forms.Button;$gd.Text='减少/删除 →';$gd.Location='450,325';$gd.Size='95,34';$gameTab.Controls.Add($gd)
    $gos.add_TextChanged(({Set-InventoryAdminFilter $gov $gos.Text @('名称','ID','载体','分类')}).GetNewClosure());$gas.add_TextChanged(({Set-InventoryAdminFilter $gav $gas.Text @('名称','ID','载体','分类','说明','效果')}).GetNewClosure())
