    $fTab=New-Object Windows.Forms.TabPage;$fTab.Text='装饰家具管理';$Tabs.TabPages.Add($fTab);$fos=New-Object Windows.Forms.TextBox;$fos.Location='15,15';$fos.Size='350,26';$fTab.Controls.Add($fos);$fas=New-Object Windows.Forms.TextBox;$fas.Location='555,15';$fas.Size='350,26';$fTab.Controls.Add($fas);$fog=New-InventoryAdminGrid $fTab 15 50 430 650;$fag=New-InventoryAdminGrid $fTab 555 50 525 650
    $fot=New-InventoryAdminTable @('名称','ID','实例','类型','已摆放','X','Y');$fov=New-Object Data.DataView;$fov.Table=$fot;$fog.DataSource=$fov;$fat=New-InventoryAdminTable @('名称','ID','类型','期限','金币','NANA','说明');foreach($x in $catalog.furniture){[void]$fat.Rows.Add($x.name,[string]$x.id,$x.type_name,[string]$x.days,[string]$x.coin,[string]$x.nana,$x.description)};$fav=New-Object Data.DataView;$fav.Table=$fat;$fag.DataSource=$fav
    $refreshFurniture={ $fot.Rows.Clear();foreach($r in $ctx.Furniture){$x=$byFurniture[[uint32]$r.code];[void]$fot.Rows.Add($(if($x){$x.name}else{"FURNITURE-$($r.code)"}),[string]$r.code,[string]$r.index,$(if($x){$x.type_name}else{$r.type}),$(if($r.placed){'是'}else{'否'}),[string]$r.x,[string]$r.y)} }.GetNewClosure();&$refreshFurniture
    $fa=New-Object Windows.Forms.Button;$fa.Text='← 添加实例';$fa.Location='450,275';$fa.Size='95,35';$fTab.Controls.Add($fa);$fd=New-Object Windows.Forms.Button;$fd.Text='删除实例 →';$fd.Location='450,325';$fd.Size='95,35';$fTab.Controls.Add($fd);$fos.add_TextChanged(({Set-InventoryAdminFilter $fov $fos.Text @('名称','ID','实例','类型','已摆放')}).GetNewClosure());$fas.add_TextChanged(({Set-InventoryAdminFilter $fav $fas.Text @('名称','ID','类型','说明')}).GetNewClosure())
    $fa.add_Click(({ $c=Get-InventoryAdminCode $fag;if(-not$c){return};if($ctx.Furniture.Count-ge254){[Windows.Forms.MessageBox]::Show('家具实例上限为254。')|Out-Null;return};$used=@($ctx.Furniture|ForEach-Object{[int]$_.index});$idx=1;while($used-contains$idx){$idx++};$x=$byFurniture[$c];[void]$ctx.Furniture.Add([pscustomobject]@{code=$c;index=$idx;placed=$false;type=[byte]$x.type;x=400;y=300;z=0;mirror=0});&$refreshFurniture}).GetNewClosure());$fd.add_Click(({ if(-not$fog.CurrentRow){return};$idx=[int]$fog.CurrentRow.Cells['实例'].Value;$r=@($ctx.Furniture|Where-Object{$_.index-eq$idx})[0];if($r){[void]$ctx.Furniture.Remove($r);&$refreshFurniture}}).GetNewClosure())

